  insert into public.brands (name, website, description, country, status) values ('Lithe Beauty', 'https://lithebeauty.ca', 'Canadian clean beauty brand (makeup and skincare) whose own Lithe Collective creator program page publishes the round''s clearest uncapped statement: its FAQ answers the earnings-limit question with ''There''s no cap, and earnings are unlimited.'' Creators earn 10% commission on every order placed through their unique link or code, their audience gets 10% off, tracking runs 30 days, payouts are monthly with a $100 minimum, and the program publishes a direct contact email (anna@lithebeauty.com). The 10% rate and the verified-uncapped cap are recorded from the brand''s own page.', 'Canada', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'anna@lithebeauty.com', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (Lithe Collective)', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://lithebeauty.ca/pages/lithe-collective.', 'https://lithebeauty.ca/pages/lithe-collective', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lithe Collective Creator Program', 'https://lithebeauty.ca/pages/lithe-collective', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lithebeauty.ca/pages/lithe-collective', 'brand_site', 'affiliate_program', 'Lithe Beauty''s own Lithe Collective page (fetched) runs the brand''s creator program directly: creators earn commission on orders placed through their unique link or code, their audience receives 10% off, tracking is 30 days, payouts are monthly with a $100 minimum payout, and the page publishes the contact email anna@lithebeauty.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lithebeauty.ca/pages/lithe-collective', 'brand_site', 'commission_rate', 'The brand''s own page states creators earn 10% commission on every order. The 10% rate is recorded. No source publishes absolute creator counts, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lithebeauty.ca/pages/lithe-collective', 'brand_site', 'commission_cap', 'The program FAQ on the brand''s own page answers the earnings-limit question verbatim: ''You''ll earn 10% commission on every order placed through your unique link or code. There''s no cap, and earnings are unlimited.'' That explicit statement on the brand''s own program page is why commission_cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 18, 13, 8, 4, '{"compensation": "10% commission plus the round''s one verified-uncapped statement on the brand''s own page (''There''s no cap, and earnings are unlimited'').", "contact_access": "A direct program contact email (anna@lithebeauty.com) is published on the program page.", "credibility": "Operating DTC brand with a detailed, current program page including payout minimums and tracking terms.", "niche_fit": "Clean makeup and skincare with a simple creator story (link or code, audience discount) that fits everyday beauty content.", "opportunity_availability": "Open application from the brand''s own program page.", "ugc_evidence": "The brand runs a named creator collective with its own program page, audience discount codes and monthly payouts; no measured creator counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Captain Blankenship', 'https://captainblankenship.com', 'Seaweed-powered clean haircare brand founded by Jana Blankenship, B Corp and Made Safe Certified. Its own Collab page states plainly: ''We offer 20% commission to all creators!'' alongside free product and gifting, with collab assets served through Dovetale. The 20% rate is recorded from the brand''s own page. No cap statement and no creator counts are published, so cap and saturation stay unknown, and no contact email appears on the page.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (Captain Blankenship Collab Program via Dovetale)', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://captainblankenship.com/pages/collab.', 'https://captainblankenship.com/pages/collab', 'needs_review', now());
