  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://captainblankenship.com/pages/collab', 'brand_site', 'affiliate_program', 'Captain Blankenship''s own Collab page (fetched) invites creators to collaborate with the brand, offering commission plus free product and gifting; the page''s collab imagery is served from uploads.dovetale.com, indicating the collab program runs through Dovetale. The brand is seaweed-powered haircare, B Corp and Made Safe Certified, founded by Jana Blankenship.', 'verified', now());
