  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 16, 7, 8, 5, '{"compensation": "20% commission to all creators is one of the strongest published rates in the round; no cap statement is published, so the cap is honestly unknown.", "contact_access": "Application runs through the brand''s own collab page/Dovetale; no program email is published.", "credibility": "B Corp and Made Safe Certified brand with a named founder and an established DTC storefront.", "niche_fit": "Clean, seaweed-powered haircare with strong certifications gives hair and clean-beauty creators a clear, credible content angle.", "opportunity_availability": "Open collab application from the brand''s own page.", "ugc_evidence": "The brand''s own page speaks directly to creators with a commission offer and gifting; no measured creator counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ByRoe', 'https://byroe.com', 'Korean superfood skincare brand founded by Amy Roe. Its own Creator Program page offers three partnership paths and leads with Shopify Collabs as the full partner program: commission on every sale, product gifting, early access to launches and creator toolkits, open to U.S.-based creators of all sizes with approval typically within 7 days. The brand does not publish the Collabs rate (''Full details are provided when you''re approved''), so the rate is null; a dated March 2024 directory listing shows a separate ShareASale program at 10%. The TikTok Shop path (up to 15%) is an extra channel only, never the recorded route. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs (BYROE Creator Program)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://byroe.com/pages/creator-program.', 'https://byroe.com/pages/creator-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BYROE Creator Program (Shopify Collabs)', 'https://byroe.com/pages/creator-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://byroe.com/pages/creator-program', 'brand_site', 'affiliate_program', 'BYROE''s own Creator Program page (fetched) presents Shopify Collabs as ''Our full partner program with gifting'' for creators on Instagram, YouTube, blogs and beyond: commission on every sale, product gifting, early access to launches and creator toolkits. The FAQ says the program is open exclusively to U.S.-based creators of all sizes, applications are typically reviewed within 7 days, and creators may also partner via TikTok Shop (up to 15% - an extra channel only) and LTK simultaneously.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/byroe/', 'affiliate_directory', 'commission_rate', 'The brand''s own page does not publish the Shopify Collabs rate (''Full details are provided when you''re approved''), so commission_rate is null. LinkClicky''s directory (March 2024) lists a separate ShareASale program for BYROE at 10% with a 30-day cookie; that dated figure is documented here but is not recorded as the current program rate. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 18, 9, 7, 9, 4, '{"compensation": "Commission on every sale is promised but the rate is unpublished (given on approval), so compensation scores low despite the program''s polish; a dated directory lists 10% on a separate ShareASale program.", "contact_access": "Application via the brand''s own page/Shopify Collabs; no program email is published.", "credibility": "Operating DTC brand with a detailed, current creator program page and clear FAQ.", "niche_fit": "Korean superfood skincare with clinical-results positioning is a strong fit for skincare routine and review content.", "opportunity_availability": "Open to all U.S.-based creators with a stated ~7-day review - unusually accessible.", "ugc_evidence": "A dedicated creator program page with toolkits, gifting and early access, explicitly welcoming creators of all sizes - the strongest creator-facing setup in the round."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Estelí', 'https://www.estelibody.com', 'Small-batch clean skincare and botanical perfume brand inspired by Nicaragua, female-founded and family-run, Leaping Bunny Certified, featured in Oprah Daily, Bustle, Nylon, The Zoe Report and Glamour. Its own Awin merchant profile actively recruits beauty and wellness bloggers, influencers and content creators (coupon/deal sites are not accepted), publishes a 30-day cookie, an $80 average order value and a dedicated affiliate support email. The commission is tiered by publisher type and the percentage is not published, so the rate is null. No cap statement is published.', 'United States', 'published') returning id into bid;
