  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 9, 12, 8, 4, '{"compensation": "A tiered commission exists but the percentage is unpublished, so compensation scores low until the rate is known.", "contact_access": "A dedicated affiliate support email (affiliates@estelibody.com) is published on the program profile.", "credibility": "Leaping Bunny Certified, female-founded brand with named national press features on its profile.", "niche_fit": "Small-batch botanical skincare with a transparent-ingredient story fits clean-beauty creators well.", "opportunity_availability": "Open application through Awin (coupon/deal sites excluded).", "ugc_evidence": "The brand''s own network profile explicitly recruits beauty bloggers, influencers and content creators and provides creative assets; no measured creator counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Evolve Organic Beauty', 'https://www.evolvebeauty.co.uk', 'Independent British organic skincare brand, B Corp certified, founder-led and made in-house in small batches since 2009, with products over 98% natural and certified organic. Its own Awin merchant profile publishes the affiliate terms: 10% commission for every new customer and 5% for returning customers, with a 30-day cookie. The 10% new-customer rate is recorded with the split documented. No cap statement or creator counts are published.', 'United Kingdom', 'published') returning id into bid;
