  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 13, 6, 8, 5, '{"compensation": "10% new / 5% returning is a fair published split; no cap statement is published, so the cap is honestly unknown.", "contact_access": "Application and management run through Awin; no program email is published on the profile.", "credibility": "B Corp certified, founder-led brand operating since 2009 with 7,000+ five-star reviews claimed on its storefront.", "niche_fit": "Certified-organic, small-batch British skincare is a clean fit for skincare and wellness creators.", "opportunity_availability": "Open application through Awin.", "ugc_evidence": "A live network programme with published terms; the profile is publisher-facing rather than creator-specific, and no creator counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Monastery', 'https://www.monasterymade.com', 'Luxury botanical skincare brand founded by an aesthetician, blending natural ingredients with high-performance formulations and sustainable, ethical sourcing. Its affiliate program runs on ShareASale at 15% per sale with a 45-day cookie, per the network listing documented by LinkClicky. The 15% ShareASale rate is recorded; a separate 3-5% figure circulates for the Amazon channel and is documented as a different channel, not a conflict on the ShareASale rate. No cap statement or creator counts are published.', 'United States', 'published') returning id into bid;
