  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/monastery/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s affiliate directory (fetched, listing updated March 2024) documents Monastery''s affiliate program on ShareASale with a 45-day cookie and a join route through ShareASale. Monastery is a luxury botanical skincare brand founded by an aesthetician, with sustainably and ethically sourced ingredients.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/monastery/', 'affiliate_directory', 'commission_rate', 'LinkClicky lists the ShareASale commission as 15% per sale (''This is just what''s officially listed with their affiliate program as the payout''). The 15% rate is recorded. Lasso''s lower 3-5% figure for Monastery reflects its Amazon channel, a different route, and is documented here rather than treated as a conflict. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
