  insert into public.brands (name, website, description, country, status) values ('Green People', 'https://www.greenpeople.co.uk', 'UK organic beauty pioneer, experts in sensitive skin since 1997, with over 150 certified-organic products across skincare, hair care, sun care and make-up. Its own Awin merchant profile publishes the affiliate terms: 8% commission on new customer transactions and 4% on return customer transactions across all product categories. The 8% new-customer rate is recorded with the split documented. No cap statement or creator counts are published.', 'United Kingdom', 'published') returning id into bid;
