  insert into public.brands (name, website, description, country, status) values ('Briogeo', 'https://www.briogeohair.com', 'Major clean haircare brand built on a ''6-Free'' promise (no harsh sulfates, silicones, phthalates, parabens, DEA or artificial dyes), with natural, scientifically backed formulas for all hair types and eco-conscious packaging. Its affiliate program runs on Impact (the join route resolves to app.impact.com). Published rate figures conflict across directories - 3%, 8-10% and 2% - so the rate is null with the conflict documented. No cap statement or creator counts are published.', 'United States', 'published') returning id into bid;
