  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/briogeo-hair/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s affiliate directory (fetched, listing updated March 2024) documents Briogeo''s affiliate program on the Impact platform, with the join route resolving to app.impact.com. Briogeo is a clean haircare brand with a ''6-Free Hair Care'' promise and formulas for all hair types.', 'publicly_reported', now());
