  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 8, 5, 8, 5, '{"compensation": "The program pays commission, but published figures conflict (3% vs 8-10% vs 2%), so the rate is honestly null and compensation scores low.", "contact_access": "Application runs through Impact; no program email is published.", "credibility": "Established, widely retailed clean haircare brand with a long-standing ingredient-transparency promise.", "niche_fit": "A leading clean haircare brand with formulas for every hair type - a natural fit for hair creators.", "opportunity_availability": "Open application through Impact.", "ugc_evidence": "A live program on a major network (Impact); no measured creator counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('By Rosie Jane', 'https://www.byrosiejane.com', 'Los Angeles clean beauty brand making fragrances and cosmetics from responsibly sourced ingredients, free from parabens, phthalates and artificial dyes; the line spans perfumes, oils, candles and cheek & lip balm pots. Its affiliate program runs on ShareASale at 12% per sale with a long 90-day cookie, per the network listing documented by LinkClicky. The 12% rate is recorded. No cap statement or creator counts are published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 12, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/by-rosie-jane/.', 'https://linkclicky.com/affiliate-program/by-rosie-jane/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'By Rosie Jane Affiliate Program (ShareASale)', 'https://linkclicky.com/affiliate-program/by-rosie-jane/', null, 'unverified', 'ugc');
