  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/by-rosie-jane/', 'affiliate_directory', 'commission_rate', 'LinkClicky lists the ShareASale commission as 12% per sale with a 90-day cookie (''This is just what''s officially listed with their affiliate program as the payout''). The 12% rate is recorded. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 14, 5, 8, 4, '{"compensation": "12% per sale with an unusually long 90-day cookie is a solid published offer; no cap statement is published, so the cap is honestly unknown.", "contact_access": "Application runs through ShareASale; no program email is published.", "credibility": "Operating DTC clean beauty brand; program terms rest on a network directory listing rather than the brand''s own page.", "niche_fit": "Clean fragrance and minimalist cosmetics fit fragrance and everyday-beauty creators.", "opportunity_availability": "Open application through ShareASale.", "ugc_evidence": "A live network program per the listing; no measured creator counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Juice Beauty', 'https://juicebeauty.com', 'Northern California organic skincare leader built on authentically organic, high-efficacy formulas. Its affiliate program, listed on Rakuten Advertising (LinkShare), pays 6% per sale and is aimed at skincare bloggers and influencers, per Lasso''s fetched program page. The 6% rate is recorded. No cap statement or creator counts are published.', 'United States', 'published') returning id into bid;
