  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/juice-beauty/', 'affiliate_directory', 'affiliate_program', 'Lasso''s Juice Beauty affiliate program page (fetched) describes the program as built for bloggers and influencers promoting organic skincare, with an application and approval flow and an affiliate dashboard; affiliateprograms.com lists the program''s network as Rakuten Advertising (LinkShare). Juice Beauty is a Northern California company leading in authentically organic, high-efficacy beauty.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/juice-beauty/', 'affiliate_directory', 'commission_rate', 'Lasso''s program page states the commission rate plainly: ''6% Per Sale'', applying to all products. The 6% rate is recorded. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 11, 5, 8, 5, '{"compensation": "6% per sale is a modest published rate; no cap statement is published, so the cap is honestly unknown.", "contact_access": "Application runs through the network; no program email is published.", "credibility": "Long-established organic beauty leader with a national retail and DTC presence.", "niche_fit": "A leading organic skincare brand with broad name recognition fits skincare creators of many sizes.", "opportunity_availability": "Open application through Rakuten Advertising.", "ugc_evidence": "A live network program described as built for bloggers and influencers; no measured creator counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Injinji', 'https://www.injinji.com', 'Performance toesock brand (founded 1999) whose patented five-toe socks are a cult staple with runners, hikers and ultrarunners. Its own affiliate page publishes an 8% commission, a 30-day cookie and a dedicated in-house affiliate manager, with the program hosted on AvantLink and applications screened by the brand.', 'United States', 'published') returning id into bid;
