  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.injinji.com/affiliates.', 'https://www.injinji.com/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Injinji Affiliate Program (AvantLink)', 'https://www.injinji.com/affiliates', 'https://www.injinji.com/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.injinji.com/affiliates', 'official_program_page', 'commission_rate', 'The brand''s own affiliate page: ''When customers follow an Affiliate''s unique URL to make an Injinji.com purchase, an 8% commission is earned'', with a 30-day cookie duration, banners/text links/product feed and a dedicated in-house affiliate manager.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.injinji.com/affiliates', 'official_program_page', 'creator_program', 'The same page invites ''a website or blog owner in the active or outdoor industry'' to apply, states the program ''is hosted by AvantLink'', and notes every applicant goes through a screening process. No cap statement appears on the page, so commission_cap stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 13, 9, 8, 4, '{"niche_fit": "Toesocks are a distinctive, demonstrable product for running, trail and foot-health content - blister-prevention and gear-test videos write themselves.", "ugc_evidence": "The brand''s own page recruits active/outdoor website and blog owners and supplies banners, text links and a product feed; it is publisher-facing rather than a social-first creator portal, so the score is mid-range.", "compensation": "8% per sale with a 30-day cookie, published on the brand''s own page; no cap statement was found, so the cap is honestly unknown.", "contact_access": "A dedicated in-house affiliate manager is promised on the page, but no direct email is published there.", "opportunity_availability": "Open application from the brand''s own page into AvantLink, free to join, with a screening step.", "credibility": "Operating since 1999 with a patented product and the full inventory on its own storefront - an established niche brand."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Crowned Athletics', 'https://crownedathletics.com', 'Women''s activewear brand with a princess-inspired design identity and a loyal Instagram community. Its own ''Crowned Crew'' affiliate program pays 10% commission on new purchases made with an affiliate''s unique code, runs through GoAffPro, and pays via PayPal - but it is selective: applicants must be current customers with a public Instagram page.', 'United States', 'published') returning id into bid;
