  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'GoAffPro', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://crownedathletics.gorgias.help/en-US/represent-crowned-athletics-187614.', 'https://crowned-athletics.goaffpro.com', 'needs_review', now());
