  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://crownedathletics.gorgias.help/en-US/represent-crowned-athletics-187614', 'official_program_page', 'commission_rate', 'The brand''s own help-centre program page: ''Affiliates earn 10% commission on any new purchases made using their unique code'', repeated in the payout terms - ''Payouts are eligible 45 days after the sale date and are issued between the 1st and 5th of each month'', paid through PayPal.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://crownedathletics.gorgias.help/en-US/represent-crowned-athletics-187614', 'official_program_page', 'creator_program', 'The same page sets the entry bar: applicants must be current customers (a purchase within the past 12 months) with a public Instagram page, must follow @CrownedAthletics, and apply via the linked GoAffPro portal (crowned-athletics.goaffpro.com). No cap statement appears, so commission_cap stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 16, 14, 7, 6, 3, '{"niche_fit": "Women''s activewear with a strong visual identity is prime fitness-fashion UGC - try-ons, gym outfits and themed collections.", "ugc_evidence": "The program is built around Instagram creators: a public Instagram page is mandatory, codes are formatted from the affiliate''s handle, and the brand claims usage rights over tagged photos for its own channels - clear, documented UGC mechanics.", "compensation": "10% on new purchases via code, published in the brand''s own terms with a defined payout schedule; no cap statement was found, so the cap is honestly unknown.", "contact_access": "Application runs through the GoAffPro portal linked from the brand''s own page; no direct partnerships email is published.", "opportunity_availability": "Selective rather than open: only current customers with a public Instagram page are considered, which limits availability.", "credibility": "A real, operating DTC brand with detailed published terms, but small and niche compared with national activewear labels."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Outdoor Vitals', 'https://outdoorvitals.com', 'Direct-to-consumer ultralight backpacking gear brand (quilts, jackets, tents) built around a ''Live Ultralight'' philosophy. Its own affiliate page publishes a 10% commission on product sales, a 30-day cookie window and an AvantLink application, and explicitly welcomes outdoor websites, blogs and social followings.', 'United States', 'published') returning id into bid;
