  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://outdoorvitals.com/pages/outdoor-vitals-affiliate-program', 'official_program_page', 'commission_rate', 'The brand''s own affiliate page: ''earn 10% commission on every qualified buyer you send our way'' and, in the program highlights, ''10% commission on product sales'' with a ''30 day cookie window''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://outdoorvitals.com/pages/outdoor-vitals-affiliate-program', 'official_program_page', 'creator_program', 'The same page asks ''Do you have a website, blog or social media following related to the outdoors?'' and states ''We''ve partnered with AvantLink'' with APPLY NOW buttons routing to AvantLink. The brand also donates 1% of revenues to poverty projects. No cap statement appears, so commission_cap stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 14, 8, 8, 4, '{"niche_fit": "Ultralight backpacking gear is core travel/adventure content - gear lists, thru-hike setups and pack shakedowns.", "ugc_evidence": "The brand''s own page explicitly recruits outdoor websites, blogs and social followings and provides AvantLink creative tools; no creator-count evidence was published, so saturation stays unknown.", "compensation": "10% on product sales with a 30-day cookie, published on the brand''s own page; no cap statement was found, so the cap is honestly unknown.", "contact_access": "Applications route through AvantLink from the brand''s page; no direct partnerships email is published on it.", "opportunity_availability": "Open application from the brand''s own page into AvantLink, free to join.", "credibility": "An established DTC outdoor brand with lifetime warranties and a documented 1%-of-revenue give-back."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('RUX', 'https://rux.life', 'Outdoor gear brand built around the RUX 70L collapsible storage-and-hauling system for road trips, camping and overlanding. Its own affiliate page publishes an 8% commission on every referred sale, a 30-day cookie and dedicated affiliate management, with sign-up through AvantLink.', 'Canada', 'published') returning id into bid;
