  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 11, 12, 8, 8, 3, '{"niche_fit": "A collapsible gear-hauling system demos well in road-trip, camping and van-life content, though the product range is narrow.", "ugc_evidence": "The brand recruits outdoor travel and gear websites/blogs through AvantLink with regularly updated creative; it is publisher-facing rather than social-creator-first.", "compensation": "8% per referred sale with a 30-day cookie, published on the brand''s own page; no cap statement was found, so the cap is honestly unknown.", "contact_access": "Dedicated affiliate management is promised on the page; applications route through AvantLink and no direct email is published.", "opportunity_availability": "Open application from the brand''s own page into AvantLink, free to join.", "credibility": "A young, single-product-line brand - real storefront and program, but a shorter track record than legacy outdoor labels."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Clarks', 'https://www.clarks.com', 'Two-century-old footwear brand (Desert Boot, Wallabee) running a US affiliate program through Ascend by Partnerize. Its own affiliate page states all affiliates start at 5% commission, with applications reviewed within five business days and a 60-day lock period on sales.', 'United Kingdom', 'published') returning id into bid;
