  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 10, 10, 7, 8, 5, '{"niche_fit": "Heritage footwear is steady fashion and travel-shoe content - outfit builds, comfort-shoe and travel-packing videos.", "ugc_evidence": "A traditional publisher affiliate program (graphics, text and product links via Partnerize) rather than a creator-first scheme; workable for UGC creators with blogs or link hubs.", "compensation": "A published 5% starting rate on the brand''s own page; higher tiers are not published and no cap statement was found, so the cap is honestly unknown.", "contact_access": "The page offers a dedicated affiliate team contact route (email masked in the fetched page, so none is recorded) plus Partnerize support.", "opportunity_availability": "Open publisher application from the brand''s own page, free, with a stated five-business-day decision.", "credibility": "A global footwear brand founded in 1825 - maximum brand credibility in this round."}'::jsonb);
