  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 7, 7, 8, 4, '{"niche_fit": "Playful men''s shorts and swim are strong summer, holiday and gifting UGC - the brand''s humour-led identity suits short-form video.", "ugc_evidence": "The program is a standard Impact publisher program; the brand itself is heavily social-led, but the fetched listing documents no creator-specific perks.", "compensation": "3% per sale is low, and the only fetched listing is from March 2024, so it is held as publicly reported; no cap statement was found, so the cap is honestly unknown.", "contact_access": "Contact runs through the Impact program dashboard; no direct partnerships email is published in the fetched source.", "opportunity_availability": "Open application through Impact from the program listing.", "credibility": "A well-known, long-running DTC menswear brand with national retail presence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Mountain Hardwear', 'https://www.mountainhardwear.com', 'Columbia Sportswear''s technical alpine brand (Ghost Whisperer insulation, tents, sleeping bags, packs). Its program runs through CJ Affiliate; the brand''s official page advertises commissions only as ''up to 10%'' - a ceiling - and third-party figures conflict (5%, 8%, 10%), so no base rate is recorded.', 'United States', 'published') returning id into bid;
