  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/mountain-hardwear/', 'affiliate_directory', 'commission_rate', 'Rate conflict, documented rather than settled: GetLasso lists 8% per sale with a 21-day cookie; afftank and linkwhisper list 10%; affiliatemarketinggirl''s March 2026 verified list gives 5% on CJ Affiliate with a 30-day cookie. Because the figures conflict, commission_rate is null.', 'publicly_reported', now());
