  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 9, 7, 8, 5, '{"niche_fit": "Technical alpine apparel and camp gear is core hiking, climbing and backpacking creator content.", "ugc_evidence": "Listings describe data feeds, banners, text links and a dedicated affiliate manager - a solid publisher toolkit, though not creator-portal-first.", "compensation": "No settled base rate: the official wording is an ''up to 10%'' ceiling and third-party figures conflict (5%/8%/10%), so the rate is honestly null; no cap statement was found, so the cap is unknown.", "contact_access": "Contact runs through the CJ Affiliate dashboard; no direct partnerships email is published in the fetched sources.", "opportunity_availability": "Open publisher application through CJ Affiliate.", "credibility": "A premium Columbia Sportswear brand with decades in technical outdoor gear."}'::jsonb);
