  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 11, 11, 6, 7, 4, '{"niche_fit": "Technical hunting apparel is a focused niche - strong fit for hunting and mountain content, narrower for general fashion creators.", "ugc_evidence": "The program''s existence on Impact is documented in network payout data; no creator-specific program page was fetched, so the evidence score is modest.", "compensation": "5% per network payout data (publicly reported, not brand-published); no cap statement was found, so the cap is honestly unknown.", "contact_access": "Contact runs through the Impact program dashboard; no direct partnerships email appears in the fetched source.", "opportunity_availability": "Application through Impact; the program is less publicly documented than this round''s network staples.", "credibility": "A well-established premium DTC brand in the hunting space with a loyal customer base."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('David', 'https://davidprotein.com', 'David (David Protein) is a US protein-bar brand built around high-protein, low-sugar bars, and runs an ambassador program through Superfiliate that pays commission on referred new customers'' first purchases.', 'United States', 'published') returning id into bid;
