  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://davidprotein.com/pages/ambassadors', 'brand_website', 'affiliate_program', 'David''s own ambassador page, fetched first-hand, publishes the program terms: ambassadors earn commission on a referred new customer''s first purchase through their unique link, eligible ambassadors receive a free sample pack, commissions are paid in the first week of each month via PayPal, Venmo or ACH, and the attribution window is 7 days, with applications running through the brand''s Superfiliate portal. The page publishes no commission percentage, so commission_rate is null. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 9, 7, 9, 4, '{"compensation": "Commission on first purchases is confirmed with monthly payouts, but the brand publishes no percentage, so no rate can be recorded.", "contact_access": "Application runs through the brand''s Superfiliate portal; no public partnerships email was published on the fetched page.", "credibility": "A well-known, fast-growing US protein brand with national retail distribution.", "niche_fit": "Protein bars are a staple, highly demonstrable product for fitness, nutrition and snack-review creators.", "opportunity_availability": "Program is live and open to apply now from the brand page.", "ugc_evidence": "A dedicated ambassador program with published community guidelines and free sample packs for eligible ambassadors."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('OraWellness', 'https://orawellness.com', 'OraWellness is a US oral-health brand selling natural tooth and gum care products since 2010, and runs an affiliate program through Refersion paying 20% commission with recurring earnings on Subscribe & Save orders.', 'United States', 'published') returning id into bid;
