  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://orawellness.com/affiliate-sign-up/.', 'https://orawellness.refersion.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'OraWellness Affiliate Program', 'https://orawellness.refersion.com', 'https://orawellness.com/affiliate-sign-up/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://orawellness.com/affiliate-sign-up/', 'brand_website', 'affiliate_program', 'OraWellness''s own affiliate sign-up page, fetched first-hand, publishes a 20% commission rate, long-term tracking (180 days), recurring commissions on Subscribe & Save orders, quarterly payouts by the 5th of January, April, July and October, and a $20 minimum payout, with affiliate accounts managed through the brand''s Refersion portal. The program requires a health or wellness website or social following (minimum 5,000 followers), US or Canada base with an EIN/SSN, and does not accept coupon-site promotion. The published 20% rate is recorded. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 16, 7, 8, 4, '{"compensation": "20% commission published on the brand''s own page, plus recurring commissions on Subscribe & Save orders and 180-day tracking; no cap statement, so the cap is unknown.", "contact_access": "Application runs through the brand''s Refersion portal; no public partnerships email was published on the fetched page.", "credibility": "Operating since 2010 with customers in more than 105 countries.", "niche_fit": "Natural oral care is a focused, underserved niche for dental-health, natural-living and wellness creators.", "opportunity_availability": "Program is live now, though approval requires an established health or wellness audience of at least 5,000 followers.", "ugc_evidence": "The program explicitly recruits health and wellness sites and social creators, with recurring subscription commissions that reward ongoing content."}'::jsonb);
