  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Just Live Affiliate Program', 'https://justlive.com/pages/affiliate', 'https://justlive.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://justlive.com/pages/affiliate', 'brand_website', 'affiliate_program', 'Just Live''s own affiliate page, fetched first-hand, publishes 15% commission on every referred purchase, paid monthly on the 5th, a 30-day cookie window, a custom 15%-off promo code for each affiliate''s audience, and bonus tiers for high-volume affiliates, with the program managed through Impact. A separate ambassador track run through Grin also pays 15% plus free product for influencers and athletes. The published 15% rate is recorded. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
