  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uk.jshealthvitamins.com/pages/affiliates', 'brand_website', 'affiliate_program', 'JSHealth''s own affiliates page, fetched first-hand, confirms a global affiliate programme spanning its AU, EU, UK and US sites plus a separate ambassador programme, free to join, offering a competitive commission per sale with bespoke structures possible, and publishes a named contact: Steph Sambrook, Global Affiliate & Partnerships Lead, at steph@jessicasepel.com. The brand page publishes no rate, and third-party figures conflict (Lasso reports up to 11.25%, a ceiling; Shopper reports 5%), so commission_rate is null and the conflict is documented here. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 8, 12, 9, 4, '{"compensation": "Commission per sale is confirmed, but the brand publishes no rate and third-party figures conflict, so no rate is recorded.", "contact_access": "A named Global Affiliate & Partnerships Lead with a direct email is published on the program page.", "credibility": "An established, founder-led Australian vitamins brand selling across four regional storefronts.", "niche_fit": "Vitamins and targeted supplements are everyday staples for health, beauty-from-within and wellness-routine creators.", "opportunity_availability": "Programme is live and free to join now from the brand page.", "ugc_evidence": "Both an affiliate programme and a distinct ambassador programme are published, showing deliberate creator recruitment across regions."}'::jsonb);
