  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Charlotte''s Web Affiliate Program', 'https://www.charlottesweb.com/pages/affiliate-program', 'https://www.charlottesweb.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.charlottesweb.com/pages/affiliate-program', 'brand_website', 'affiliate_program', 'Charlotte''s Web''s own affiliate program page, fetched first-hand, states ''Earn 10% on every order, with opportunities to increase your commission'', with monthly payouts after orders are confirmed, commission boosts during sales periods and for high performers, and a free account created in under 60 seconds; the page names no network, so the route is recorded as brand direct. The brand''s own published 10% rate is recorded. Third-party reports conflict with it and with each other (Lasso reports 15% via CJ; some blogs report 30%; AffRoom reports ''from 10%'' via ShareASale or in-house), and that conflict is documented here. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 13, 7, 9, 5, '{"compensation": "10% on every order published on the brand''s own page, with stated opportunities to increase and periodic boosts; no cap statement, so the cap is unknown.", "contact_access": "Sign-up runs from the brand''s own program page; no public partnerships email was published on the fetched page.", "credibility": "The best-known name in US CBD, founded by the Stanley brothers and publicly traded, with the category''s longest track record.", "niche_fit": "CBD oils, gummies and topicals for calm, sleep and recovery are core content for wellness and health creators.", "opportunity_availability": "Program is live with a fast, free sign-up from the brand page.", "ugc_evidence": "A live brand-run affiliate program with performance boosts; creator-specific perks beyond commission are not detailed."}'::jsonb);
