  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nuleafnaturals.com/pages/affiliate-program', 'brand_website', 'affiliate_program', 'NuLeaf Naturals'' own affiliate program page, fetched first-hand, states ''We pay you a 20% commission'' on every sale made through an affiliate''s unique link or 20%-off coupon code, with commissions paid monthly through the Impact Partnership Cloud by EFT or PayPal, applications reviewed within 2 to 3 business days, no website required, and a published affiliate team email, affiliates@nuleafnaturals.com. The brand''s own published flat 20% rate is recorded; a third-party roundup (AffRoom) instead describes tiered terms of up to 30% on new customers and 10% on returning customers, which conflicts with the brand page and is documented here. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
