  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cbdmd.com/pages/affiliate-program', 'brand_website', 'affiliate_program', 'cbdMD''s own affiliate program page, fetched first-hand, publishes 20% commission on every referred purchase, a 90-day cookie window, a 15%-off coupon code for each affiliate''s audience, banner and social creative assets, and tracking through the Impact affiliate dashboard, with a published affiliate contact email, affiliates@cbdmd.com. Commissions land in the affiliate''s balance after a 60-day period tied to the brand''s money-back guarantee; affiliates must be 18 or older, may join from any country, and the brand ships within the United States only. The published 20% rate is recorded. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
