  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.extractlabs.com/resources/common-questions/', 'brand_website', 'affiliate_program', 'Extract Labs'' own Common Questions page, fetched first-hand, answers ''How can I partner with Extract Labs?'' by stating that affiliates earn a 15% commission on each sale, sign up through the website for a personal link or coupon code, track sales through the Impact Radius Network and receive monthly payouts; the page also publishes the brand''s support email, support@extractlabs.com. The brand''s own published 15% rate is recorded; third-party directories conflict with it (Lasso reports 20%, LinkClicky reports 10%), and that conflict is documented here. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 15, 8, 9, 4, '{"compensation": "15% commission published on the brand''s own site with monthly payouts via Impact; no cap statement, so the cap is unknown.", "contact_access": "Affiliate sign-up runs through the brand website and a general support email is published; no dedicated partnerships email was published.", "credibility": "Veteran-founded, with USDA Organic-certified products, a GMP-certified facility and batch-level certificates of analysis.", "niche_fit": "A wide cannabinoid range across oils, gummies, topicals and pet products fits wellness, recovery and pet creators.", "opportunity_availability": "Program is live and joinable now through the brand website.", "ugc_evidence": "The program is published on the brand''s own FAQ with a link-and-code model for independent promoters, though creator-specific recruitment is light."}'::jsonb);
