  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/32809', 'network_profile', 'affiliate_program', 'NatPat''s official Awin merchant profile (NatPat US Affiliate Program, profile 32809), fetched first-hand, publishes a 15% default commission rate on new and return customer sales, a 30-day cookie period, and categories of Health, Wellness, Children''s Health, Vitamins and Health Patch. The brand sells worldwide with a UK, US and AU focus, particularly wants partners who can market to parents and partners in the health and wellness space, does not work with voucher sites, and requires applicants to email a seven-question business case to its affiliate management team at elliot.myers@tama.consulting before network approval. The published 15% rate is recorded. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 15, 12, 7, 3, '{"compensation": "15% default commission on new and return customer sales published on the official Awin profile; no cap statement, so the cap is unknown.", "contact_access": "The affiliate management team''s email is published directly on the Awin profile for applications and partnership discussion.", "credibility": "A growing Australian family-wellness brand with worldwide sales; smaller and younger than the category leaders.", "niche_fit": "Chemical-free patches for kids'' sleep, bites and focus are a natural fit for parenting, family and natural-living creators.", "opportunity_availability": "Program is live on Awin, but approval requires a written business case, a heavier gate than a standard application.", "ugc_evidence": "The profile explicitly seeks parent-focused and health-and-wellness content partners and offers tenancy budget and content collaboration."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Soundcore', 'https://www.soundcore.com', 'Audio brand of Anker Innovations — wireless earbuds, headphones, Bluetooth speakers and Nebula projectors — sold through soundcore.com. Its own Become An Affiliate page invites review sites, online communities, bloggers and other content website owners to promote the brand, publishing a 3%-15% commission range on all approved sales, a 30-day cookie and free joining.', 'United States', 'published') returning id into bid;
