  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Soundcore Affiliate Program — brand''s own page publishes 3%-15% commission on all approved sales (recorded at the 3% floor), 30-day cookie, free to join', 'https://www.soundcore.com/become-an-affiliate', 'https://www.soundcore.com/become-an-affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.soundcore.com/become-an-affiliate', 'official_site', 'affiliate', 'Soundcore''s own affiliate page fetched in full: ''Free to join'', ''3%-15% commission on all approved sales (excludes returns and cancellations)'', ''Up to 15% commissions on all sales'', 30-day cookies, product feed, banners and promotional coupon codes, and the published contact service@soundcore.com. The recorded 3% is the floor of the range the brand itself publishes. The page names no network — application is through soundcore.com. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/soundcore/', 'listing', 'affiliate', 'Corroboration: Lasso reports the Soundcore program at 5% to 7% per sale with a 30-day cookie, and Shopper reports 5% — both figures sit inside the 3%-15% range the brand''s own page publishes, so they corroborate rather than conflict with it.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 12, 10, 7, 5, '{"compensation": "The brand publishes a wide 3%-15% range; the recorded floor is modest and where in the range a creator lands is not published, and no cap statement exists", "contact_access": "Direct application on the brand''s own page plus a published contact email (service@soundcore.com)", "credibility": "Anker Innovations is a large, established global consumer-electronics company and Soundcore is its flagship audio line", "niche_fit": "Earbuds, headphones and portable speakers are core tech-review UGC \u2014 sound tests, unboxings and best-under-a-budget roundups are natural content", "opportunity_availability": "Free to join, but the page describes the program as enabling ''select affiliates'', so approval is not automatic", "ugc_evidence": "A brand-published program aimed at review sites, online communities, bloggers and content website owners; genuine creator/publisher evidence, but no dedicated creator tier is published"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Logitech', 'https://www.logitech.com', 'Global computer-peripherals company — mice, keyboards, webcams, headsets and the Logitech G, ASTRO, Blue and Ultimate Ears brands — sold through logitech.com. One affiliate program on Impact covers the whole family of brands; its own affiliate page publishes per-brand standard rates but contradicts itself on the headline standard rate, so no single rate is settled.', 'Switzerland', 'published') returning id into bid;
