  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.logitech.com/en-us/ergo/ergo-affiliate-program.html.', 'https://www.logitech.com/en-us/ergo/ergo-affiliate-program.html', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Logitech Affiliate Program — one Impact program covering Logitech, Logitech G, ASTRO, Blue and Ultimate Ears; brand page publishes per-brand rates (5%-15%) but contradicts its own ''up to 10% standard'' wording, so the rate is unsettled; contact logitechaffiliateus@digitalriver.com', 'https://www.logitech.com/en-us/ergo/ergo-affiliate-program.html', 'https://www.logitech.com/en-us/ergo/ergo-affiliate-program.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.logitech.com/en-us/ergo/ergo-affiliate-program.html', 'official_site', 'affiliate', 'Logitech''s own affiliate page fetched in full: the program runs on Impact (''apply through our affiliate program vender, Impact''), covers Logitech, Logitech G, Ultimate Ears, Astro and Blue, is free with no minimum sales requirement, uses a 30-day cookie, and publishes the affiliate contact logitechaffiliateus@digitalriver.com. On rates the same page states ''You can earn up to a 10% standard commission on all products'' and ''Get paid up to 15% commission!'', and prints a per-brand standard-rate table — Logitech 15%, Ultimate Ears 10%, Logitech G 5%, Astro 5%, Blue 5% — alongside a sales-level table listing ''All products 15%''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.whichprogram.com/en/p/logitech-affiliate-program', 'listing', 'affiliate', 'Rate-conflict note: directories that read the official program (WhichProgram; StreamerPerks'' October 2026 read of the official pages) report a 4% to 10% range on Impact with a 30-day cookie, and Lasso reports 4%. Because the brand''s own page contradicts itself (up to 10% standard vs a 15% table entry) and directories read 4-10%, commission_rate is null with the conflict documented here; the network is Impact per the brand''s own page. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 10, 12, 8, 5, '{"compensation": "Published figures span 4% to 15% depending on brand and source, and the brand''s own page contradicts itself, so compensation is scored on unsettled evidence; no cap statement exists", "contact_access": "Published affiliate-program email (logitechaffiliateus@digitalriver.com) on the brand''s own page, plus the Impact application route", "credibility": "One of the world''s largest peripherals makers, publicly traded, with a long-running documented program", "niche_fit": "Desk-setup, gaming and work-from-home peripherals are among the most-reviewed products in tech UGC, and one program covers five creator-friendly brands", "opportunity_availability": "Free to join with no minimum sales requirement; anyone may apply, subject to acceptance", "ugc_evidence": "A brand-published affiliate program on Impact plus a separate Logitech G creator program; strong publisher evidence, though the affiliate page itself is publisher-framed"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Razer', 'https://www.razer.com', 'Gaming hardware company — Blade laptops, gaming mice, keyboards, headsets and streaming gear — sold through razer.com. Its affiliate program runs on Impact in 40+ markets; the brand''s marketing page advertises up to 15%, while Razer''s own published program terms set the actual payout table at 2.5%-5% by product category.', 'United States', 'published') returning id into bid;
