  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.razer.com/affiliate', 'https://www.razer.com/affiliate', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.razer.com/affiliate.', 'https://www.razer.com/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Razer Affiliate Program — Impact terms publish 5% on most products (2.5% on laptops); the brand page''s ''up to 15%'' is a ceiling, not the standard rate', 'https://www.razer.com/affiliate', 'https://www.razer.com/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.razer.com/affiliate', 'official_site', 'affiliate', 'Razer''s own affiliate page: ''Earn up to 15% commission on every sale'', sales credited up to 14 days after click, 40+ global markets, real-time tracking, no joining fee, paid on monthly net sales through Impact (the application form signs affiliates in to impact.com, and the FAQ points other affiliates to the ''Razer Affiliate Program'' campaign on the Impact marketplace). Streamers and influencers are routed through the #RazerStreamer program and may be selected for the affiliate program case-by-case. The 15% is a ceiling claim, not the standard rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://assets2.razerzone.com/pdf/Affiliate/Razer_Affiliate_Program_TemplateTerms_JP.pdf', 'official_site', 'affiliate', 'Razer''s own published Impact template terms (brand-domain document) set the actual payout table: Online Sale 2.5%-5% — laptops 2.5%, non-Blade products 5%, all other products 5% — with software & services, SWAG and a peripherals master list at 0%, and loyalty/coupon/discount-code affiliates capped at 1% under the program policy. The recorded 5% is the terms'' standard rate for most products. No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 11, 9, 7, 5, '{"compensation": "The published terms pay 5% on most products and 2.5% on laptops \u2014 modest on high-ticket gear; the advertised 15% is only a ceiling and no cap statement exists", "contact_access": "Application runs through the brand''s own page into Impact; no direct affiliate email is published", "credibility": "A leading global gaming-lifestyle brand with terms published on its own domain", "niche_fit": "Gaming peripherals and Blade laptops are a staple of gaming and streaming UGC \u2014 reviews, setups and loadout content are natural fits", "opportunity_availability": "Open on the Impact marketplace to affiliates 18+; accounts with no sales for six consecutive months are terminated", "ugc_evidence": "A brand-published program on Impact with a dedicated streamer/influencer route (#RazerStreamer); influencers join the affiliate program case-by-case after selection"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Zens', 'https://zens.tech', 'Wireless-charging brand founded in 2011 at the High Tech Campus in Eindhoven — multi-device chargers, power banks, cables and adapters — sold through zens.tech. Its own affiliate page recruits publishers, reviewers and creators into a program run on Awin, publishing at least 7% commission on approved sales with a 30-day cookie.', 'Netherlands', 'published') returning id into bid;
