  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 14, 13, 9, 8, 4, '{"compensation": "A brand-published floor of at least 7% on premium-priced chargers is fair, transparent pay; no cap statement exists", "contact_access": "Application runs through the brand''s own page into Awin; the page offers a team contact route but publishes no affiliate email", "credibility": "Operating since 2011 from Eindhoven''s High Tech Campus, with products featured by major tech press; a smaller brand than the global majors in this batch", "niche_fit": "Wireless chargers and power banks slot naturally into desk-setup, travel-kit and everyday-carry tech content", "opportunity_availability": "Open application through Awin for relevant publishers and creators, subject to approval", "ugc_evidence": "The brand''s own page explicitly courts creators and publishers and showcases creator content; a genuine but publisher-led program"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Mammotion', 'https://us.mammotion.com', 'Outdoor-robotics company behind the LUBA and YUKA wire-free robot lawn mowers, sold through its regional stores including us.mammotion.com. Its own affiliate page publishes 3% of each order through Impact, a $1500+ average order value, dedicated 1v1 support and the affiliate contact affiliate.os@mammotion.com.', 'China', 'published') returning id into bid;
