  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 13, 9, 12, 8, 4, '{"compensation": "Only 3%, but on a $1500+ average order that is roughly $45 per sale; no cap statement exists", "contact_access": "Published affiliate email (affiliate.os@mammotion.com) on the program page, plus the Impact application route and promised 1v1 support", "credibility": "An established outdoor-robotics brand founded in 2022 with global retail presence and a complete, terms-bearing program page", "niche_fit": "Robot lawn mowers are a fast-growing lawn-tech demo category \u2014 yard transformations and mower tests are watchable home UGC, though narrower than mainstream smart home", "opportunity_availability": "Open application through Impact across 30+ countries", "ugc_evidence": "A brand-published program whose own FAQ includes influencer networks among its affiliate types; publisher-led, with no dedicated creator tier published"}'::jsonb);
