  insert into public.brands (name, website, description, country, status) values ('Bare Home', 'https://barehome.com', 'Bedding and sleep-essentials brand — sheet sets, comforters, duvets, blankets, pillows and mattresses with OEKO-TEX and GOTS certifications — sold through barehome.com. Its Awin merchant profile is written for creators, influencers and bloggers and publishes a standard commission of 5% on new customers and 2% on returning customers, with the affiliate team contact BareHome@jebcommerce.com.', 'United States', 'published') returning id into bid;
