  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/96949', 'listing', 'affiliate', 'Bare Home''s own Awin merchant profile fetched in full: ''Our affiliate program is designed for creators, influencers, bloggers, and website owners'', ''Commission range: program standard rate is 5% new | 2% returning; subject to differ based on factors such as promotional type'', creative resources provided, applications reviewed for brand fit, and ''Reach out to our affiliate team: BareHome@jebcommerce.com''. The recorded 5% is the profile''s published standard rate for new customers. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
