  insert into public.brands (name, website, description, country, status) values ('Hydro Flask', 'https://www.hydroflask.com', 'Insulated bottle and drinkware brand — vacuum-insulated bottles, tumblers, coolers and accessories — sold through hydroflask.com. Its Awin merchant profile publishes a tiered commission structure with a dedicated 10% rate for content and influencer partners, a 30-day cookie and dedicated agency support at affiliates@vervaunt.com.', 'United States', 'published') returning id into bid;
