  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Hydro Flask Affiliate Programme — Awin profile publishes 10% commission for content and influencer partners (5% cashback/loyalty, 3% voucher); contact affiliates@vervaunt.com', 'https://ui.awin.com/merchant-profile/119849', 'https://ui.awin.com/merchant-profile/119849', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/119849', 'listing', 'affiliate', 'Hydro Flask''s own Awin merchant profile fetched in full: ''OUR COMMISSION STRUCTURE — 3% for all voucher code publishers; 5% for all cashback and loyalty publishers; 10% for content and influencer partners; 10% for closed user groups'', a 30-day cookie period, £30 average order value, a regularly updated product feed, and ''Dedicated support from our affiliate agency affiliates@vervaunt.com''. The recorded 10% is the profile''s published content-and-influencer tier — the creator-relevant rate. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
