  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 13, 11, 7, 5, '{"compensation": "10% for content and influencer partners is solid published pay on a mid-priced product; lower tiers apply to other partner types and no cap statement exists", "contact_access": "Published affiliate agency email (affiliates@vervaunt.com) on the profile, plus the Awin application route", "credibility": "A category-defining global drinkware brand with a long retail history", "niche_fit": "Insulated bottles are everyday-carry staples across outdoor, fitness, school and desk content \u2014 among the most-photographed products in lifestyle UGC", "opportunity_availability": "Application through Awin, subject to approval; the fetched profile is the UK programme", "ugc_evidence": "The network profile carries a dedicated, published content-and-influencer partner tier \u2014 direct creator evidence, though the program is network-run"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Meross', 'https://shop.meross.com', 'Smart-home brand — smart plugs, switches, bulbs, garage-door openers and Matter/HomeKit devices — sold through shop.meross.com and major retailers. Its program terms on Awin confirm a live affiliate program whose allowed partner types explicitly include Communities and UGC and content creators and influencers, with registration through the Meross official store; no commission rate is published on any page fetched.', 'China', 'published') returning id into bid;
