  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/advertiser-terms/107077?setLocale=en_GB', 'listing', 'affiliate', 'Meross Smarthome''s Awin program terms fetched in full (last updated 23 Dec 2025): the terms confirm a live Awin program, list allowed partner types including ''Communities and UGC'', ''Content creators and influencers'', ''Social traffic'' and ''Editorial content'', set out commission validation rules (commission is calculated on transaction value including VAT/sales tax, delivery and fees, with no product categories excluded), and state that participation in the Meross Affiliate Referral Program requires a registration form submitted to shop.meross.com. The terms publish no commission rate.', 'publicly_reported', now());
