  insert into public.brands (name, website, description, country, status) values ('Dr. Bill''s Pet Nutrition', 'https://drbillspetnutrition.com', 'Veterinarian-developed pet supplement brand — canine and feline supplements for joint, digestive, skin and coat, immune and cognitive support, made in the USA — sold through drbillspetnutrition.com. Its own partner program page publishes 20% commission, a 30-day cookie, monthly PayPal payouts and lifetime attribution of referred customers, and explicitly recruits pet creators on TikTok, Instagram and YouTube.', 'United States', 'published') returning id into bid;
