  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://drbillspetnutrition.com/partner-program/.', 'https://drbillspetnutrition.com/partner-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Dr. Bill''s Pet Nutrition Partner Program — brand''s own page publishes 20% commission, 30-day cookie, monthly PayPal payouts and lifetime customer attribution', 'https://drbillspetnutrition.com/partner-program/', 'https://drbillspetnutrition.com/partner-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://drbillspetnutrition.com/partner-program/', 'official_site', 'affiliate', 'Dr. Bill''s Pet Nutrition''s own partner page fetched in full: ''We Offer Our Partners 20% Commission!'', affiliates receive a unique 15-20% coupon code for their audience, cookies run 30 days, referred customers are permanently tagged so partners earn on every future purchase (an attribution term, not an earnings-cap statement, so the cap stays unknown), payments are monthly via PayPal with a $50 minimum threshold, all products are commission-eligible, and the page''s ''Who We''re Looking For'' section explicitly welcomes creators on TikTok, Instagram, Facebook and YouTube. Program requirements include FTC disclosure compliance and promoting at least once per month. The recorded 20% is the brand''s own published rate.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 16, 17, 9, 7, 3, '{"compensation": "20% is the highest published rate in this batch, with lifetime attribution of referred customers on top; no cap statement exists", "contact_access": "Application form on the brand''s own partner page with a dedicated affiliate support team promised; no direct email is published", "credibility": "A smaller, single-founder brand; its ''over 3,000 vets recommending for 40 years'' claims are brand-reported and not independently verified", "niche_fit": "Pet supplements for joint, digestion and coat health map directly onto pet-owner content \u2014 senior-dog care, rescue stories and coat transformations are natural UGC", "opportunity_availability": "Application with approval, and partners must promote at least once per month to stay in the program", "ugc_evidence": "The brand''s own page explicitly recruits TikTok, Instagram, Facebook and YouTube pet creators by name \u2014 direct, unambiguous creator evidence"}'::jsonb);
